/** Original, reviewed micro-lessons; source pages identify curriculum, not reproduced questions. */
import {L,S,Q} from './authoring.mjs';
export const quadraticTrigSkills=[];
export const skillLessons=quadraticTrigSkills;
const B=s=>{const i=s.indexOf('｜');if(i<0)throw Error('Missing translation');return L(s.slice(0,i),s.slice(i+1).replaceAll('验','驗').replaceAll('两','兩').replaceAll('种','種'));};
const T=s=>s?.replaceAll('§','\\');
const ST=([s,m])=>{const p=B(s);return S(p.en,p.zh,T(m));};
function q(kind,level,taskType,prompt,expression,answer,hints,steps,result,explanation,conditions,extra={}){
 const p=B(prompt);return Q(kind,level,p.en,p.zh,T(expression),answer,hints.map(B),steps.map(ST),B(result),B(explanation),
 {taskType,difficultyReview:'reviewed',conditions:conditions.map(B),examScopes:['JM01','JM02'],...extra});
}
const opt=(id,text,misconceptionCode)=>({id,label:B(text),misconceptionCode});
const R=['All inputs are real unless a smaller domain is stated.｜除另訂較小定義域外，輸入均為實數。'];
const source=(section,printedPage)=>({documentId:'textbook-c1',pdfPage:printedPage+7,printedPage,section});
function pack(s){
 const bind=(items,d)=>items.map((x,i)=>({...x,id:d?'diagnostic-'+s.id+'-'+(i+1):'skill-'+s.id+'-'+(i<3?'example-'+(i+1):'exercise-'+(i-2)),
 source:{type:'original',lessonId:s.id,relatedDocumentId:'textbook-c1'},skills:[s.id],primarySkillIds:[s.id],
 ...(x.kind==='written'?{rubric:x.steps.map(v=>v.body)}:{})}));
 const result={...s,bookId:'c1',chapterId:'c1-'+s.source.section.split('.')[0],section:s.source.section,status:'authored',
 familyTitle:B(s.familyId==='quadratics'?'Quadratics｜二次函數':'Trigonometry｜三角函數'),
 title:B(s.title),summary:B(s.summary),objectives:s.objectives.map(B),misconceptions:s.misconceptions.map(B),
 questions:bind(s.questions,false),diagnostics:bind(s.diagnostics,true)};
 quadraticTrigSkills.push(result);return result;
}
const concept=(title,body,formula,motivation,derivation,conditions,counterexample,representations)=>({
 title:B(title),body:B(body),formula:T(formula),motivation:B(motivation),derivation:derivation.map(ST),conditions:conditions.map(B),counterexample:B(counterexample),representations:representations.map(B)});
function teach(stages,prompts,board,anticipated,followups,remediation,exit,rubric){
 return {timing:stages.map(([title,activity],i)=>({minutes:[5,8,10,12,5][i],title:B(title),activity:B(activity)})),
 prompts:prompts.map(B),board:board.map(([s,m])=>({...B(s),math:T(m)})),anticipated:anticipated.map(B),followups:followups.map(B),remediation:remediation.map(B),exit:exit.map(B),rubric:rubric.map(([s,sample])=>({...B(s),sample:B(sample)}))};
}
const inquiry=(id,prediction,explanation,transfer,model)=>({type:'skill',modelId:id,prediction:B(prediction),explanation:B(explanation),transfer:B(transfer),model:B(model)});

